import{_ as t,a0 as d,w as o,s as c,I as a,x as n,a1 as p,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Sed 命令完全指南 | LCTT x X-CMD","titleTemplate":false,"description":"Sed 命令完全指南 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Sed 命令完全指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Sed 命令完全指南 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180615 Complete Sed Command Guide [Explained with Practical Examples]","title":"Sed 命令完全指南","tag":"201811","desc":""},"relativePath":"201811/20180615 Complete Sed Command Guide [Explained with Practical Examples].md","filePath":"[post].md"}'),r={name:"201811/20180615 Complete Sed Command Guide [Explained with Practical Examples].md"};function h(g,s,u,b,k,f){const e=d("Link");return o(),c("div",null,[s[89]||(s[89]=a("h1",{id:"sed-命令完全指南",tabindex:"-1"},[n("Sed 命令完全指南 "),a("a",{class:"header-anchor",href:"#sed-命令完全指南","aria-label":"Permalink to “Sed 命令完全指南”"},"​")],-1)),a("p",null,[s[2]||(s[2]=n("在前面的文章中，我展示了 ",-1)),p(e,{href:"https://linuxhandbook.com/sed-command-basics/"},{default:i(()=>[...s[0]||(s[0]=[n("Sed 命令的基本用法",-1)])]),_:1}),s[3]||(s[3]=n("， Sed 是一個實用的流編輯器。今天，我們準備去了解關於 Sed 更多的知識，深入瞭解 Sed 的運行模式。這將是你全面瞭解 Sed 命令的一個機會，深入挖掘它的運行細節和精妙之處。因此，如果你已經做好了準備，那就打開終端吧，",-1)),p(e,{href:"https://gist.github.com/s-leroux/5cb36435bac46c10cfced26e4bf5588c"},{default:i(()=>[...s[1]||(s[1]=[n("下載測試文件",-1)])]),_:1}),s[4]||(s[4]=n(" 然後坐在電腦前：開始我們的探索之旅吧！",-1))]),s[90]||(s[90]=l('<h3 id="關於-sed-的一點點理論知識" tabindex="-1">關於 Sed 的一點點理論知識 <a class="header-anchor" href="#關於-sed-的一點點理論知識" aria-label="Permalink to “關於 Sed 的一點點理論知識”">​</a></h3><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05/sed-reference-guide.jpeg?resize=702%2C395&amp;ssl=1" alt="complete reference guide to sed commands"></p><h4 id="首先我們看一下-sed-的運行模式" tabindex="-1">首先我們看一下 sed 的運行模式 <a class="header-anchor" href="#首先我們看一下-sed-的運行模式" aria-label="Permalink to “首先我們看一下 sed 的運行模式”">​</a></h4><p>要準確理解 Sed 命令，你必須先了解工具的運行模式。</p><p>當處理數據時，Sed 從輸入源一次讀入一行，並將它保存到所謂的<ruby>模式空間<rt>pattern space</rt></ruby>中。所有 Sed 的變換都發生在模式空間。變換都是由命令列上或外部 Sed 腳本文件提供的單字母命令來描述的。大多數 Sed 命令都可以由一個地址或一個地址範圍作為前導來限制它們的作用範圍。</p><p>默認情況下，Sed 在結束每個處理循環後輸出模式空間中的內容，也就是説，輸出發生在輸入的下一個行覆蓋模式空間之前。我們可以將這種運行模式總結如下：</p><ol><li>嘗試將下一個行讀入到模式空間中</li><li>如果讀取成功： <ol><li>按腳本中的順序將所有命令應用到與那個地址匹配的當前輸入行上</li><li>如果 sed 沒有以靜默模式（<code>-n</code>）運行，那麼將輸出模式空間中的所有內容（可能會是修改過的）。</li><li>重新回到 1。</li></ol></li></ol><p>因此，在每個行被處理完畢之後，模式空間中的內容將被丟棄，它並不適合長時間保存內容。基於這種目的，Sed 有第二個緩衝區：<ruby>保持空間<rt>hold space</rt></ruby>。除非你顯式地要求它將數據置入到保持空間、或從保持空間中取得數據，否則 Sed 從不清除保持空間的內容。在我們後面學習到 <code>exchange</code>、<code>get</code>、<code>hold</code> 命令時將深入研究它。</p><h4 id="sed-的抽象機制" tabindex="-1">Sed 的抽象機制 <a class="header-anchor" href="#sed-的抽象機制" aria-label="Permalink to “Sed 的抽象機制”">​</a></h4><p>你將在許多的 Sed 教程中都會看到上面解釋的模式。的確，這是充分正確理解大多數基本 Sed 程序所必需的。但是當你深入研究更多的高級命令時，你將會發現，僅這些知識還是不夠的。因此，我們現在嘗試去了解更深入的一些知識。</p>',10)),a("p",null,[s[10]||(s[10]=n("的確，Sed 可以被視為是",-1)),p(e,{href:"http://mathworld.wolfram.com/AbstractMachine.html"},{default:i(()=>[...s[5]||(s[5]=[n("抽象機制",-1)])]),_:1}),s[11]||(s[11]=n("的實現，它的",-1)),p(e,{href:"https://en.wikipedia.org/wiki/State_(computer_science)"},{default:i(()=>[...s[6]||(s[6]=[n("狀態",-1)])]),_:1}),s[12]||(s[12]=n("由三個",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Data_buffer"},{default:i(()=>[...s[7]||(s[7]=[n("緩衝區",-1)])]),_:1}),s[13]||(s[13]=n(" 、兩個",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Processor_register#Categories_of_registers"},{default:i(()=>[...s[8]||(s[8]=[n("寄存器",-1)])]),_:1}),s[14]||(s[14]=n("和兩個",-1)),p(e,{href:"https://www.computerhope.com/jargon/f/flag.htm"},{default:i(()=>[...s[9]||(s[9]=[n("標誌",-1)])]),_:1}),s[15]||(s[15]=n("來定義的：",-1))]),s[91]||(s[91]=l(`<ul><li><strong>三個緩衝區</strong>用於去保存任意長度的文本。是的，是三個！在前面的基本運行模式中我們談到了兩個：模式空間和保持空間，但是 Sed 還有第三個緩衝區：<ruby>追加隊列<rt>append queue</rt></ruby>。從 Sed 腳本的角度來看，它是一個只寫緩衝區，Sed 將在它運行時的預定義階段來自動刷新它（一般是在從輸入源讀入一個新行之前，或僅在它退出運行之前）。</li><li>Sed 也維護<strong>兩個寄存器</strong>：<ruby>行計數器<rt>line counter</rt></ruby>（LC）用於保存從輸入源讀取的行數，而<ruby>程序計數器<rt>program counter</rt></ruby>（PC）總是用來保存下一個將要運行的命令的索引（就是腳本中的位置），Sed 將它作為它的主循環的一部分來自動增加 PC。但在使用特定的命令時，腳本也可以直接修改 PC 去跳過或重複執行程序的一部分。這就像使用 Sed 實現的一個循環或條件語句。更多內容將在下面的專用分支一節中描述。</li><li>最後，<strong>兩個標誌</strong>可以修改某些 Sed 命令的行為：<ruby>自動輸出<rt>auto-print</rt></ruby>（AP）標誌和<ruby>替換<rt> substitution</rt></ruby>（SF）標誌。當自動輸出標誌 AP 被設置時，Sed 將在模式空間的內容被覆蓋前自動輸出（尤其是，包括但不限於，在從輸入源讀入一個新行之前）。當自動輸出標誌被清除時（即：沒有設置），Sed 在腳本中沒有顯式命令的情況下，將不會輸出模式空間中的內容。你可以通過在“靜默模式”（使用命令列選項 <code>-n</code> 或者在第一行或腳本中使用特殊註釋 <code>#n</code>）運行 Sed 命令來清除自動輸出標誌。當它的地址和查找模式與模式空間中的內容都匹配時，替換標誌 SF 將被替換命令（<code>s</code> 命令）設置。替換標誌在每個新的循環開始時、或當從輸入源讀入一個新行時、或獲得條件分支之後將被清除。我們將在分支一節中詳細研究這一話題。</li></ul><p>另外，Sed 維護一個進入到它的地址範圍（關於地址範圍的更多知識將在地址範圍一節詳細描述）的命令列表，以及用於讀取和寫入數據的兩個文件句柄（你將在讀取和寫入命令的描述中獲得更多有關文件句柄的內容）。</p><h4 id="一個更精確的-sed-運行模式" tabindex="-1">一個更精確的 Sed 運行模式 <a class="header-anchor" href="#一個更精確的-sed-運行模式" aria-label="Permalink to “一個更精確的 Sed 運行模式”">​</a></h4><p>一圖勝千言，所以我畫了一個流程圖去描述 Sed 的運行模式。我將兩個東西放在了旁邊，像處理多個輸入文件或錯誤處理，但是我認為這足夠你去理解任何 Sed 程序的行為了，並且可以避免你在編寫你自己的 Sed 腳本時浪費在摸索上的時間。</p><p><img src="https://i1.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-flowchart.png?w=702&amp;ssl=1" alt="The Sed execution model"></p><p>你可能已經注意到，在上面的流程圖上我並沒有描述特定的命令動作。對於命令，我們將逐個詳細講解。因此，不用着急，我們馬上開始！</p><h3 id="打印命令" tabindex="-1">打印命令 <a class="header-anchor" href="#打印命令" aria-label="Permalink to “打印命令”">​</a></h3><p>打印命令（<code>p</code>）是用於輸出在它運行那一刻模式空間中的內容。它並不會以任何方式改變 Sed 抽象機制中的狀態。</p><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-print-command.png?w=702&amp;ssl=1" alt="The Sed  command"></p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -e &#39;p&#39; inputfile</span></span></code></pre></div><p>上面的命令將輸出輸入文件中每一行的內容……兩次，因為你一旦顯式地要求使用 <code>p</code> 命令時，將會在每個處理循環結束時再隱式地輸出一次（因為在這裏我們不是在“靜默模式”中運行 Sed）。</p><p>如果我們不想每個行看到兩次，我們可以用兩種方式去解決它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;p&#39; inputfile # 在靜默模式中顯式輸出</span></span>
<span class="line"><span>sed -e &#39;&#39; inputfile # 空的“什麼都不做的”程序，隱式輸出</span></span></code></pre></div><p>注意：<code>-e</code> 選項是引入一個 Sed 命令。它被用於區分命令和文件名。由於一個 Sed 表達式必須包含至少一個命令，所以對於第一個命令，<code>-e</code> 標誌不是必需的。但是，由於我個人使用習慣問題，為了與在這裏的大多數的一個命令列上給出多個 Sed 表達式的更復雜的案例保持一致性，我添加了它。你自己去判斷這是一個好習慣還是壞習慣，並且在本文的後面部分還將延用這一習慣。</p><h3 id="地址" tabindex="-1">地址 <a class="header-anchor" href="#地址" aria-label="Permalink to “地址”">​</a></h3><p>顯而易見，<code>print</code> 命令本身並沒有太多的用處。但是，如果你在它之前添加一個地址，這樣它就只輸出輸入文件的一些行，這樣它就突然變得能夠從一個輸入文件中過濾一些不希望的行。那麼 Sed 的地址又是什麼呢？它是如何來辨別輸入文件的“行”呢？</p><h4 id="行號" tabindex="-1">行號 <a class="header-anchor" href="#行號" aria-label="Permalink to “行號”">​</a></h4><p>Sed 的地址既可以是一個行號（<code>$</code> 表示“最後一行”）也可以是一個正則表達式。在使用行號時，你需要記住 Sed 中的行數是從 1 開始的 —— 並且需要注意的是，它<strong>不是</strong>從 0 行開始的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;1p&#39; inputfile # 僅輸出文件的第一行</span></span>
<span class="line"><span>sed -n -e &#39;5p&#39; inputfile # 僅輸出第 5 行</span></span>
<span class="line"><span>sed -n -e &#39;$p&#39; inputfile # 輸出文件的最後一行</span></span>
<span class="line"><span>sed -n -e &#39;0p&#39; inputfile # 結果將是報錯，因為 0 不是有效的行號</span></span></code></pre></div>`,20)),a("p",null,[s[17]||(s[17]=n("根據 ",-1)),p(e,{href:"http://pubs.opengroup.org/onlinepubs/9699919799/utilities/sed.html"},{default:i(()=>[...s[16]||(s[16]=[n("POSIX 規範",-1)])]),_:1}),s[18]||(s[18]=n("，如果你指定了幾個輸出文件，那麼它的行號是累加的。換句話説，當 Sed 打開一個新輸入文件時，它的行計數器是不會被重置的。因此，以下的兩個命令所做的事情是一樣的。僅輸出一行文本：",-1))]),s[92]||(s[92]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;1p&#39; inputfile1 inputfile2 inputfile3</span></span>
<span class="line"><span>cat inputfile1 inputfile2 inputfile3 | sed -n -e &#39;1p&#39;</span></span></code></pre></div><p>實際上，確實在 POSIX 中規定了多個文件是如何處理的：</p><blockquote><p>如果指定了多個文件，將按指定的文件命名順序進行讀取並被串聯編輯。</p></blockquote><p>但是，一些 Sed 的實現提供了命令列選項去改變這種行為，比如， GNU Sed 的 <code>-s</code> 標誌（在使用 GNU Sed <code>-i</code> 標誌時，它也被隱式地應用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -sn -e &#39;1p&#39; inputfile1 inputfile2 inputfile3</span></span></code></pre></div><p>如果你的 Sed 實現支持這種非標準選項，那麼關於它的具體細節請查看 <code>man</code> 手冊頁。</p><h4 id="正則表達式" tabindex="-1">正則表達式 <a class="header-anchor" href="#正則表達式" aria-label="Permalink to “正則表達式”">​</a></h4><p>我前面説過，Sed 地址既可以是行號也可以是正則表達式。那麼正則表達式是什麼呢？</p>`,8)),a("p",null,[s[20]||(s[20]=n("正如它的名字，一個",-1)),p(e,{href:"https://www.regular-expressions.info/"},{default:i(()=>[...s[19]||(s[19]=[n("正則表達式",-1)])]),_:1}),s[21]||(s[21]=n("是描述一個字符串集合的方法。如果一個指定的字符串符合一個正則表達式所描述的集合，那麼我們就認為這個字符串與正則表達式匹配。",-1))]),s[93]||(s[93]=a("p",null,"正則表達式可以包含必須完全匹配的文本字符。例如，所有的字母和數字，以及大部分可以打印的字符。但是，一些符號有特定意義：",-1)),a("ul",null,[s[25]||(s[25]=a("li",null,[n("它們相當於錨，像 "),a("code",null,"^"),n(" 和 "),a("code",null,"$"),n(" 它們分別表示一個行的開始和結束；")],-1)),s[26]||(s[26]=a("li",null,[n("能夠做為整個字符集的佔位符的其它符號（比如圓點 "),a("code",null,"."),n(" 可以匹配任意單個字符，或者方括號 "),a("code",null,"[]"),n(" 用於定義一個自定義的字符集）；")],-1)),a("li",null,[s[23]||(s[23]=n("另外的是表示重複出現的數量（像 ",-1)),p(e,{href:"https://chortle.ccsu.edu/FiniteAutomata/Section07/sect07_16.html"},{default:i(()=>[...s[22]||(s[22]=[n("克萊尼星號（",-1),a("code",null,"*",-1),n("）",-1)])]),_:1}),s[24]||(s[24]=n(" 表示前面的模式出現 0、1 或多次）；",-1))])]),s[94]||(s[94]=l(`<p>這篇文章的目的不是給大家講正則表達式。因此，我只粘幾個示例。但是，你可以在網絡上隨便找到很多關於正則表達式的教程，正則表達式的功能非常強大，它可用於許多標準的 Unix 命令和編程語言中，並且是每個 Unix 用户應該掌握的技能。</p><p>下面是使用 Sed 地址的幾個示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;/systemd/p&#39; inputfile # 僅輸出包含字符串“systemd”的行</span></span>
<span class="line"><span>sed -n -e &#39;/nologin$/p&#39; inputfile # 僅輸出以“nologin”結尾的行</span></span>
<span class="line"><span>sed -n -e &#39;/^bin/p&#39; inputfile # 僅輸出以“bin”開頭的行</span></span>
<span class="line"><span>sed -n -e &#39;/^$/p&#39; inputfile # 僅輸出空行（即：開始和結束之間什麼都沒有的行）</span></span>
<span class="line"><span>sed -n -e &#39;/./p&#39; inputfile # 僅輸出包含字符的行（即：非空行）</span></span>
<span class="line"><span>sed -n -e &#39;/^.$/p&#39; inputfile # 僅輸出只包含一個字符的行</span></span>
<span class="line"><span>sed -n -e &#39;/admin.*false/p&#39; inputfile # 僅輸出包含字符串“admin”後面有字符串“false”的行（在它們之間有任意數量的任意字符）</span></span>
<span class="line"><span>sed -n -e &#39;/1[0,3]/p&#39; inputfile # 僅輸出包含一個“1”並且後面是一個“0”或“3”的行</span></span>
<span class="line"><span>sed -n -e &#39;/1[0-2]/p&#39; inputfile # 僅輸出包含一個“1”並且後面是一個“0”、“1”、“2”或“3”的行</span></span>
<span class="line"><span>sed -n -e &#39;/1.*2/p&#39; inputfile # 僅輸出包含字符“1”後面是一個“2”（在它們之間有任意數量的字符）的行</span></span>
<span class="line"><span>sed -n -e &#39;/1[0-9]*2/p&#39; inputfile # 僅輸出包含字符“1”後面跟着“0”、“1”、或更多數字，最後面是一個“2”的行</span></span></code></pre></div><p>如果你想在正則表達式（包括正則表達式分隔符）中去除字符的特殊意義，你可以在它前面使用一個反斜槓：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 輸出所有包含字符串“/usr/sbin/nologin”的行</span></span>
<span class="line"><span>sed -ne &#39;/\\/usr\\/sbin\\/nologin/p&#39; inputfile</span></span></code></pre></div><p>並不限制你只能使用斜槓作為地址中正則表達式的分隔符。你可以通過在第一個分隔符前面加上反斜槓（<code>\\</code>）的方式，來使用任何你認為適合你需要和偏好的其它字符作為正則表達式的分隔符。當你用地址與帶文件路徑的字符一起來匹配的時，是非常有用的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 以下兩個命令是完全相同的</span></span>
<span class="line"><span>sed -ne &#39;/\\/usr\\/sbin\\/nologin/p&#39; inputfile</span></span>
<span class="line"><span>sed -ne &#39;\\=/usr/sbin/nologin=p&#39; inputfile</span></span></code></pre></div><h4 id="擴展的正則表達式" tabindex="-1">擴展的正則表達式 <a class="header-anchor" href="#擴展的正則表達式" aria-label="Permalink to “擴展的正則表達式”">​</a></h4>`,8)),a("p",null,[s[29]||(s[29]=n("默認情況下，Sed 的正則表達式引擎僅理解 ",-1)),p(e,{href:"https://www.regular-expressions.info/posix.html#bre"},{default:i(()=>[...s[27]||(s[27]=[n("POSIX 基本正則表達式",-1)])]),_:1}),s[30]||(s[30]=n(" 的語法。如果你需要用到 ",-1)),p(e,{href:"https://www.regular-expressions.info/posix.html#ere"},{default:i(()=>[...s[28]||(s[28]=[n("擴展正則表達式",-1)])]),_:1}),s[31]||(s[31]=n("，你必須在 Sed 命令上添加 ",-1)),s[32]||(s[32]=a("code",null,"-E",-1)),s[33]||(s[33]=n(" 標誌。擴展正則表達式在基本正則表達式基礎上增加了一組額外的特性，並且很多都是很重要的，它們所要求的反斜槓要少很多。我們來比較一下：",-1))]),s[95]||(s[95]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;/\\(www\\)\\|\\(mail\\)/p&#39; inputfile</span></span>
<span class="line"><span>sed -En -e &#39;/(www)|(mail)/p&#39; inputfile</span></span></code></pre></div><h4 id="花括號量詞" tabindex="-1">花括號量詞 <a class="header-anchor" href="#花括號量詞" aria-label="Permalink to “花括號量詞”">​</a></h4>`,2)),a("p",null,[s[35]||(s[35]=n("正則表達式之所以強大的一個原因是",-1)),p(e,{href:"https://www.regular-expressions.info/repeat.html#limit"},{default:i(()=>[...s[34]||(s[34]=[n("範圍量詞",-1)])]),_:1}),s[36]||(s[36]=n()),s[37]||(s[37]=a("code",null,"{,}",-1)),s[38]||(s[38]=n("。事實上，當你寫一個不太精確匹配的正則表達式時，量詞 ",-1)),s[39]||(s[39]=a("code",null,"*",-1)),s[40]||(s[40]=n(" 就是一個非常完美的符號。但是，（用花括號量詞）你可以顯式在它邊上添加一個下限和上限，這樣就有了很好的靈活性。當量詞範圍的下限省略時，下限被假定為 0。當上限被省略時，上限被假定為無限大：",-1))]),s[96]||(s[96]=l(`<div class="table-wrap"><table><thead><tr><th>括號</th><th>速記詞</th><th>解釋</th></tr></thead><tbody><tr><td><code>{,}</code></td><td><code>*</code></td><td>前面的規則出現 0、1、或許多遍</td></tr><tr><td><code>{,1}</code></td><td><code>?</code></td><td>前面的規則出現 0 或 1 遍</td></tr><tr><td><code>{1,}</code></td><td><code>+</code></td><td>前面的規則出現 1 或許多遍</td></tr><tr><td><code>{n,n}</code></td><td><code>{n}</code></td><td>前面的規則精確地出現 n 遍</td></tr></tbody></table></div><p>花括號在基本正則表達式中也是可以使用的，但是它要求使用反斜槓。根據 POSIX 規範，在基本正則表達式中可以使用的量詞僅有星號（<code>*</code>）和花括號（使用反斜槓，如 <code>\\{m,n\\}</code>）。許多正則表達式引擎都擴展支持 <code>\\?</code> 和 <code>\\+</code>。但是，為什麼魔鬼如此有誘惑力呢？因為，如果你需要這些量詞，使用擴展正則表達式將不但易於寫而且可移植性更好。</p><p>為什麼我要花點時間去討論關於正則表達式的花括號量詞，這是因為在 Sed 腳本中經常用這個特性去計數字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -En -e &#39;/^.{35}$/p&#39; inputfile # 輸出精確包含 35 個字符的行</span></span>
<span class="line"><span>sed -En -e &#39;/^.{0,35}$/p&#39; inputfile # 輸出包含 35 個字符或更少字符的行</span></span>
<span class="line"><span>sed -En -e &#39;/^.{,35}$/p&#39; inputfile # 輸出包含 35 個字符或更少字符的行</span></span>
<span class="line"><span>sed -En -e &#39;/^.{35,}$/p&#39; inputfile # 輸出包含 35 個字符或更多字符的行</span></span>
<span class="line"><span>sed -En -e &#39;/.{35}/p&#39; inputfile # 你自己指出它的輸出內容（這是留給你的測試題）</span></span></code></pre></div><h4 id="地址範圍" tabindex="-1">地址範圍 <a class="header-anchor" href="#地址範圍" aria-label="Permalink to “地址範圍”">​</a></h4><p>到目前為止，我們使用的所有地址都是唯一地址。在我們使用一個唯一地址時，命令是應用在與那個地址匹配的行上。但是，Sed 也支持地址範圍。Sed 命令可以應用到那個地址範圍中從開始到結束的所有地址中的所有行上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;1,5p&#39; inputfile # 僅輸出 1 到 5 行</span></span>
<span class="line"><span>sed -n -e &#39;5,$p&#39; inputfile # 從第 5 行輸出到文件結尾</span></span>
<span class="line"><span>sed -n -e &#39;/www/,/systemd/p&#39; inputfile # 輸出與正則表達式 /www/ 匹配的第一行到與接下來匹配正則表達式 /systemd/ 的行為止</span></span></code></pre></div><p>（LCTT 譯註：下面用的一個生成的列表例子，如下供參考：）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n</span></span>
<span class="line"><span>     1	ad</span></span>
<span class="line"><span>     2	ae</span></span>
<span class="line"><span>     3	af</span></span>
<span class="line"><span>     4	bd</span></span>
<span class="line"><span>     5	be</span></span>
<span class="line"><span>     6	bf</span></span>
<span class="line"><span>     7	cd</span></span>
<span class="line"><span>     8	ce</span></span>
<span class="line"><span>     9	cf</span></span></code></pre></div><p>如果在開始和結束地址上使用了同一個行號，那麼範圍就縮小為那個行。事實上，如果第二個地址的數字小於或等於地址範圍中選定的第一個行的數字，那麼僅有一個行被選定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n | sed -ne &#39;4,4p&#39;</span></span>
<span class="line"><span>     4 bd</span></span>
<span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n | sed -ne &#39;4,3p&#39;</span></span>
<span class="line"><span>     4 bd</span></span></code></pre></div><p>下面有點難了，但是在前面的段落中給出的規則也適用於起始地址是正則表達式的情況。在那種情況下，Sed 將對正則表達式匹配的第一個行的行號和給定的作為結束地址的顯式的行號進行比較。再強調一次，如果結束行號小於或等於起始行號，那麼這個範圍將縮小為一行：</p><p>（LCTT 譯註：此處作者陳述有誤，Sed 會在處理以正則表達式表示的開始行時，並不會同時測試結束表達式：從匹配開始行的正則表達式開始，直到不匹配時，才會測試結束行的表達式——無論是否是正則表達式——並在結束的表達式測試不通過時停止，並循環此測試。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 這個 /b/,4 地址將匹配三個單行</span></span>
<span class="line"><span># 因為每個匹配的行有一個行號 &gt;= 4</span></span>
<span class="line"><span>#（LCTT 譯註：結果正確，但是説明不正確。4、5、6 行都會因為匹配開始正則表達式而通過，第 7 行因為不匹配開始正則表達式，所以開始比較行數： 7 &gt; 4，遂停止。）</span></span>
<span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n | sed -ne &#39;/b/,4p&#39;</span></span>
<span class="line"><span>     4  bd</span></span>
<span class="line"><span>     5  be</span></span>
<span class="line"><span>     6  bf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 你自己指出匹配的範圍是多少</span></span>
<span class="line"><span># 第二個例子：</span></span>
<span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n | sed -ne &#39;/d/,4p&#39;</span></span>
<span class="line"><span>     1  ad</span></span>
<span class="line"><span>     2  ae</span></span>
<span class="line"><span>     3  af</span></span>
<span class="line"><span>     4  bd</span></span>
<span class="line"><span>     7  cd</span></span></code></pre></div><p>但是，當結束地址是一個正則表達式時，Sed 的行為將不一樣。在那種情況下，地址範圍的第一行將不會與結束地址進行檢查，因此地址範圍將至少包含兩行（當然，如果輸入數據不足的情況除外）：</p><p>（LCTT 譯註：如上譯註，當滿足開始的正則表達式時，並不會測試結束的表達式；僅當不滿足開始的表達式時，才會測試結束表達式。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n | sed -ne &#39;/b/,/d/p&#39;</span></span>
<span class="line"><span> 4 bd</span></span>
<span class="line"><span> 5 be</span></span>
<span class="line"><span> 6 bf</span></span>
<span class="line"><span> 7 cd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>printf &quot;%s\\n&quot; {a,b,c}{d,e,f} | cat -n | sed -ne &#39;4,/d/p&#39;</span></span>
<span class="line"><span> 4 bd</span></span>
<span class="line"><span> 5 be</span></span>
<span class="line"><span> 6 bf</span></span>
<span class="line"><span> 7 cd</span></span></code></pre></div><p>（LCTT 譯註：對地址範圍的總結，當滿足開始的條件時，從該行開始，並不測試該行是否滿足結束的條件；從下一行開始測試結束條件，並在結束條件不滿足時結束；然後對剩餘的行，再從開始條件開始匹配，以此循環——也就是説，匹配結果可以是非連續的單/多行。大家可以調整上述命令列的條件以理解。）</p><h4 id="補集" tabindex="-1">補集 <a class="header-anchor" href="#補集" aria-label="Permalink to “補集”">​</a></h4><p>在一個地址選擇行後面添加一個感嘆號（<code>!</code>）表示不匹配那個地址。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;5!p&#39; inputfile # 輸出除了第 5 行外的所有行</span></span>
<span class="line"><span>sed -n -e &#39;5,10!p&#39; inputfile # 輸出除了第 5 到 10 之間的所有行</span></span>
<span class="line"><span>sed -n -e &#39;/sys/!p&#39; inputfile # 輸出除了包含字符串“sys”的所有行</span></span></code></pre></div><h4 id="交集" tabindex="-1">交集 <a class="header-anchor" href="#交集" aria-label="Permalink to “交集”">​</a></h4><p>（LCTT 譯註：原文標題為“合集”，應為“交集”）</p><p>Sed 允許在一個塊中使用花括號 <code>{…}</code> 組合命令。你可以利用這個特性去組合幾個地址的交集。例如，我們來比較下面兩個命令的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;/usb/{</span></span>
<span class="line"><span>  /daemon/p</span></span>
<span class="line"><span>}&#39; inputfile</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sed -n -e &#39;/usb.*daemon/p&#39; inputfile</span></span></code></pre></div><p>通過在一個塊中嵌套命令，我們將在任意順序中選擇包含字符串 “usb” 和 “daemon” 的行。而正則表達式 “usb.*daemon” 將僅匹配在字符串 “daemon” 前面包含 “usb” 字符串的行。</p><p>離題太長時間後，我們現在重新回去學習各種 Sed 命令。</p><h3 id="退出命令" tabindex="-1">退出命令 <a class="header-anchor" href="#退出命令" aria-label="Permalink to “退出命令”">​</a></h3><p>退出命令（<code>q</code>）是指在當前的迭代循環處理結束之後停止 Sed。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-quit-command.png?w=702&amp;ssl=1" alt="The Sed quit command"></p><p><code>q</code> 命令是在到達輸入文件的尾部之前停止處理輸入的方法。為什麼會有人想去那樣做呢？</p><p>很好的問題，如果你還記得，我們可以使用下面的命令來輸出文件中第 1 到第 5 的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;1,5p&#39; inputfile</span></span></code></pre></div><p>對於大多數 Sed 的實現方式，工具將循環讀取輸入文件的所有行，那怕是你只處理結果中的前 5 行。如果你的輸入文件包含了幾百萬行（或者更糟糕的情況是，你從一個無限的數據流，比如像 <code>/dev/urandom</code> 中讀取）將有重大影響。</p><p>使用退出命令，相同的程序可以被修改的更高效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -e &#39;5q&#39; inputfile</span></span></code></pre></div><p>由於我在這裏並不使用 <code>-n</code> 選項，Sed 將在每個循環結束後隱式輸出模式空間的內容。但是在你處理完第 5 行後，它將退出，並且因此不會去讀取更多的數據。</p><p>我們能夠使用一個類似的技巧只輸出文件中一個特定的行。這也是從命令列中提供多個 Sed 表達式的幾種方法。下面的三個變體都可以從 Sed 中接受幾個命令，要麼是不同的 <code>-e</code> 選項，要麼是在相同的表達式中新起一行，或用分號（<code>;</code>）隔開：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n -e &#39;5p&#39; -e &#39;5q&#39; inputfile</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sed -n -e &#39;</span></span>
<span class="line"><span>  5p</span></span>
<span class="line"><span>  5q</span></span>
<span class="line"><span>&#39; inputfile</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sed -n -e &#39;5p;5q&#39; inputfile</span></span></code></pre></div><p>如果你還記得，我們在前面看到過能夠使用花括號將命令組合起來，在這裏我們使用它來防止相同的地址重複兩次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 組合命令</span></span>
<span class="line"><span>sed -e &#39;5{</span></span>
<span class="line"><span>  p</span></span>
<span class="line"><span>  q</span></span>
<span class="line"><span>}&#39; inputfile</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 可以簡寫為：</span></span>
<span class="line"><span>sed &#39;5{p;q;}&#39; inputfile</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 作為 POSIX 擴展，有些實現方式可以省略閉花括號之前的分號：</span></span>
<span class="line"><span>sed &#39;5{p;q}&#39; inputfile</span></span></code></pre></div><h3 id="替換命令" tabindex="-1">替換命令 <a class="header-anchor" href="#替換命令" aria-label="Permalink to “替換命令”">​</a></h3><p>你可以將替換命令（<code>s</code>）想像為 Sed 的“查找替換”功能，這個功能在大多數的“所見即所得”的編輯器上都能找到。Sed 的替換命令與之類似，但比它們更強大。替換命令是 Sed 中最著名的命令之一，在網上有大量的關於這個命令的文檔。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-substitution-command.png?w=702&amp;ssl=1" alt="The Sed  command"></p>`,44)),a("p",null,[p(e,{href:"https://linuxhandbook.com/?p=128"},{default:i(()=>[...s[41]||(s[41]=[n("在前一篇文章",-1)])]),_:1}),s[42]||(s[42]=n("中我們已經講過它了，因此，在這裏就不再重複了。但是，如果你對它的使用不是很熟悉，那麼你需要記住下面的這些關鍵點：",-1))]),a("ul",null,[s[46]||(s[46]=l("<li>替換命令有兩個參數：查找模式和替換字符串：<code>sed s/:/-----/ inputfile</code></li><li><code>s</code> 命令和它的參數是用任意一個字符來分隔的。這主要看你的習慣，在 99% 的時間中我都使用斜槓，但也會用其它的字符：<code>sed s%:%-----% inputfile</code>、<code>sed sX:X-----X inputfile</code> 或者甚至是 <code>sed &#39;s : ----- &#39; inputfile</code></li><li>默認情況下，替換命令僅被應用到模式空間中匹配到的第一個字符串上。你可以通過在命令之後指定一個匹配指數作為標誌來改變這種情況：<code>sed &#39;s/:/-----/1&#39; inputfile</code>、<code>sed &#39;s/:/-----/2&#39; inputfile</code>、<code>sed &#39;s/:/-----/3&#39; inputfile</code>、…</li><li>如果你想執行一個全局替換（即：在模式空間上的每個非重疊匹配上進行），你需要增加 <code>g</code> 標誌：<code>sed &#39;s/:/-----/g&#39; inputfile</code></li><li>在字符串替換中，出現的任何一個 <code>&amp;</code> 符號都將被與查找模式匹配的子字符串替換：<code>sed &#39;s/:/-&amp;&amp;&amp;-/g&#39; inputfile</code>、<code>sed &#39;s/.../&amp; /g&#39; inputfile</code></li>",5)),a("li",null,[s[44]||(s[44]=l("圓括號（在擴展的正則表達式中的 <code>(...)</code> ，或者基本的正則表達式中的 <code>\\(...\\)</code>）被當做<ruby>捕獲組<rt>capturing group</rt></ruby>。那是匹配字符串的一部分，可以在替換字符串中被引用。<code>\\1</code> 是第一個捕獲組的內容，<code>\\2</code> 是第二個捕獲組的內容，依次類推：<code>sed -E &#39;s/(.)(.)/\\2\\1/g&#39; inputfile</code>、<code>sed -E &#39;s/(.):x:.:(.*)/\\1:\\3/&#39; inputfile</code>（後者之所能正常工作是因為 ",15)),p(e,{href:"https://www.regular-expressions.info/repeat.html#greedy"},{default:i(()=>[...s[43]||(s[43]=[n("正則表達式中的量詞星號表示儘可能多的匹配，直到不匹配為止",-1)])]),_:1}),s[45]||(s[45]=n("，並且它可以匹配許多個字符）",-1))]),s[47]||(s[47]=a("li",null,[n("在查找模式或替換字符串時，你可以通過使用一個反斜槓來去除任何字符的特殊意義："),a("code",null,"sed 's/:/--\\&--/g' inputfile"),n("，"),a("code",null,"sed 's/\\//\\\\/g' inputfile")],-1))]),s[97]||(s[97]=l(`<p>所有的這些看起來有點抽象，下面是一些示例。首先，我想去顯示我的測試輸入文件的第一個字段並給它在右側附加 20 個空格字符，我可以這樣寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &lt; inputfile -E -e &#39;</span></span>
<span class="line"><span> s/:/ /             # 用 20 個空格替換第一個字段的分隔符</span></span>
<span class="line"><span> s/(.{20}).*/\\1/    # 只保留一行的前 20 個字符</span></span>
<span class="line"><span> s/.*/| &amp; |/        # 為了輸出好看添加豎條</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>第二個示例是，如果我想將用户 sonia 的 UID/GID 修改為 1100，我可以這樣寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -En -e &#39;</span></span>
<span class="line"><span>  /sonia/{</span></span>
<span class="line"><span>    s/[0-9]+/1100/g</span></span>
<span class="line"><span>    p</span></span>
<span class="line"><span> }&#39; inputfile</span></span></code></pre></div><p>注意在替換命令結束部分的 <code>g</code> 選項。這個選項改變了它的行為，因此它將查找全部的模式空間並替換，如果沒有那個選項，它只替換查找到的第一個。</p><p>順便説一下，這也是使用前面講過的輸出（<code>p</code>）命令的好機會，可以在命令運行時輸出修改前後的模式空間的內容。因此，為了獲得替換前後的內容，我可以這樣寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -En -e &#39;</span></span>
<span class="line"><span>  /sonia/{</span></span>
<span class="line"><span>     p</span></span>
<span class="line"><span>     s/[0-9]+/1100/g</span></span>
<span class="line"><span>     p</span></span>
<span class="line"><span> }&#39; inputfile</span></span></code></pre></div><p>事實上，替換後輸出一個行是很常見的用法，因此，替換命令也接受 <code>p</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -En -e &#39;/sonia/s/[0-9]+/1100/gp&#39; inputfile</span></span></code></pre></div><p>最後，我就不詳細講替換命令的 <code>w</code> 選項了，我們將在稍後的學習中詳細介紹。</p><h3 id="刪除命令" tabindex="-1">刪除命令 <a class="header-anchor" href="#刪除命令" aria-label="Permalink to “刪除命令”">​</a></h3><p>刪除命令（<code>d</code>）用於清除模式空間的內容，然後立即開始下一個處理循環。這樣它將會跳過隱式輸出模式空間內容的行為，即便是你設置了自動輸出標誌（AP）也不會輸出。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-delete-command.png?w=702&amp;ssl=1" alt="The Sed  command"></p><p>只輸出一個文件前五行的一個很低效率的方法將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -e &#39;6,$d&#39; inputfile</span></span></code></pre></div><p>你猜猜看，我為什麼説它很低效率？如果你猜不到，建議你再次去閲讀前面的關於退出命令的章節，答案就在那裏！</p><p>當你組合使用正則表達式和地址，從輸出中刪除匹配的行時，刪除命令將非常有用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -e &#39;/systemd/d&#39; inputfile</span></span></code></pre></div><h3 id="次行命令" tabindex="-1">次行命令 <a class="header-anchor" href="#次行命令" aria-label="Permalink to “次行命令”">​</a></h3><p>如果 Sed 命令沒有運行在靜默模式中，這個命令（<code>n</code>）將輸出當前模式空間的內容，然後，在任何情況下它將讀取下一個輸入行到模式空間中，並使用新的模式空間中的內容來運行當前循環中剩餘的命令。</p><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-next-command.png?w=702&amp;ssl=1" alt="The Sed next command"></p><p>用次行命令去跳過行的一個常見示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -n -e &#39;n;n;p&#39;</span></span></code></pre></div><p>在上面的例子中，Sed 將隱式地讀取輸入文件的第一行。但是次行命令將丟棄對模式空間中的內容的輸出（不輸出是因為使用了 <code>-n</code> 選項），並從輸入文件中讀取下一行來替換模式空間中的內容。而第二個次行命令做的事情和前一個是一模一樣的，這就實現了跳過輸入文件 2 行的目的。最後，這個腳本顯式地輸出包含在模式空間中的輸入文件的第三行的內容。然後，Sed 將啓動一個新的循環，由於次行命令，它會隱式地讀取第 4 行的內容，然後跳過它，同樣地也跳過第 5 行，並輸出第 6 行。如此循環，直到文件結束。總體來看，這個腳本就是讀取輸入文件然後每三行輸出一行。</p><p>使用次行命令，我們也可以找到一些顯示輸入文件的前五行的幾種方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -n -e &#39;1{p;n;p;n;p;n;p;n;p}&#39;</span></span>
<span class="line"><span>cat -n inputfile | sed -n -e &#39;p;n;p;n;p;n;p;n;p;q&#39;</span></span>
<span class="line"><span>cat -n inputfile | sed -e &#39;n;n;n;n;q&#39;</span></span></code></pre></div><p>更有趣的是，如果你需要根據一些地址來處理行時，次行命令也非常有用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -n &#39;/pulse/p&#39; # 輸出包含 “pulse” 的行</span></span>
<span class="line"><span>cat -n inputfile | sed -n &#39;/pulse/{n;p}&#39; # 輸出包含 “pulse” 之後的行</span></span>
<span class="line"><span>cat -n inputfile | sed -n &#39;/pulse/{n;n;p}&#39;  # 輸出包含 “pulse” 的行的下一行的下一行</span></span></code></pre></div><h3 id="使用保持空間" tabindex="-1">使用保持空間 <a class="header-anchor" href="#使用保持空間" aria-label="Permalink to “使用保持空間”">​</a></h3><p>到目前為止，我們所看到的命令都是僅使用了模式空間。但是，我們在文章的開始部分已經提到過，還有第二個緩衝區：保持空間，它完全由用户管理。它就是我們在第二節中描述的目標。</p><h4 id="交換命令" tabindex="-1">交換命令 <a class="header-anchor" href="#交換命令" aria-label="Permalink to “交換命令”">​</a></h4><p>正如它的名字所表示的，交換命令（<code>x</code>）將交換保持空間和模式空間的內容。記住，你只要沒有把任何東西放入到保持空間中，那麼保持空間就是空的。</p><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-exchange-command.png?w=702&amp;ssl=1" alt="The Sed exchange command"></p><p>作為第一個示例，我們可使用交換命令去反序輸出一個輸入文件的前兩行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -n -e &#39;x;n;p;x;p;q&#39;</span></span></code></pre></div><p>當然，在你設置保持空間之後你並沒有立即使用它的內容，因為只要你沒有顯式地去修改它，保持空間中的內容就保持不變。在下面的例子中，我在輸入一個文件的前五行後，使用它去刪除第一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -n -e &#39;</span></span>
<span class="line"><span> 1{x;n} # 交換保持和模式空間</span></span>
<span class="line"><span>        # 保存第 1 行到保持空間中</span></span>
<span class="line"><span>        # 然後讀取第 2 行</span></span>
<span class="line"><span> 5{</span></span>
<span class="line"><span>   p    # 輸出第 5 行</span></span>
<span class="line"><span>   x    # 交換保持和模式空間</span></span>
<span class="line"><span>        # 去取得第 1 行的內容放回到模式空間</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 1,5p   # 輸出第 2 到第 5 行</span></span>
<span class="line"><span>        # (並沒有輸錯！嘗試找出這個規則</span></span>
<span class="line"><span>        # 沒有在第 1 行上運行的原因 ;)</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h4 id="保持命令" tabindex="-1">保持命令 <a class="header-anchor" href="#保持命令" aria-label="Permalink to “保持命令”">​</a></h4><p>保持命令（<code>h</code>）是用於將模式空間中的內容保存到保持空間中。但是，與交換命令不同的是，模式空間中的內容不會被改變。保持命令有兩種用法：</p><ul><li><code>h</code> 將複製模式空間中的內容到保持空間中，覆蓋保持空間中任何已經存在的內容。</li><li><code>H</code> 將模式空間中的內容追加到保持空間中，使用一個新行作為分隔符。</li></ul><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-hold-command.png?w=702&amp;ssl=1" alt="The Sed hold command"></p><p>上面使用交換命令的例子可以使用保持命令重寫如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -n -e &#39;</span></span>
<span class="line"><span> 1{h;n} # 保存第 1 行的內容到保持緩衝區並繼續</span></span>
<span class="line"><span> 5{     # 在第 5 行</span></span>
<span class="line"><span>   x    # 交換模式和保持空間</span></span>
<span class="line"><span>        # (現在模式空間包含了第 1 行)</span></span>
<span class="line"><span>   H    # 在保持空間的第 5 行後追加第 1 行</span></span>
<span class="line"><span>   x    # 再次交換第 5 行和第 1 行，第 5 行回到模式空間</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 1,5p   # 輸出第 2 行到第 5 行</span></span>
<span class="line"><span>        # (沒有輸錯！嘗試去找到為什麼這個規則</span></span>
<span class="line"><span>        # 不在第 1 行上運行 ;)</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h4 id="獲取命令" tabindex="-1">獲取命令 <a class="header-anchor" href="#獲取命令" aria-label="Permalink to “獲取命令”">​</a></h4><p>獲取命令（<code>g</code>）與保持命令恰好相反：它從保持空間中取得內容並將它置入到模式空間中。同樣它也有兩種方式：</p><ul><li><code>g</code> 將複製保持空間中的內容並將其放入到模式空間，覆蓋模式空間中已存在的任何內容</li><li><code>G</code> 將保持空間中的內容追加到模式空間中，並使用一個新行作為分隔符</li></ul><p><img src="https://i1.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-get-command.png?w=702&amp;ssl=1" alt="The Sed get command"></p><p>將保持命令和獲取命令一起使用，可以允許你去存儲並調回數據。作為一個小挑戰，我讓你重寫前一節中的示例，將輸入文件的第 1 行放置在第 5 行之後，但是這次必須使用獲取和保持命令（使用大寫或小寫命令的版本）而不能使用交換命令。帶點小運氣，可以更簡單！</p><p>同時，我可以給你展示另一個示例，它能給你一些靈感。目標是將擁有登錄 shell 權限的用户與其它用户分開：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -En -e &#39;</span></span>
<span class="line"><span> \\=(/usr/sbin/nologin|/bin/false)$= { H;d; }</span></span>
<span class="line"><span>            # 追回匹配的行到保持空間</span></span>
<span class="line"><span>            # 然後繼續下一個循環</span></span>
<span class="line"><span> p          # 輸出其它行</span></span>
<span class="line"><span> $ { g;p }  # 在最後一行上</span></span>
<span class="line"><span>            # 獲取並打印保持空間中的內容</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h3 id="複習打印、刪除和次行命令" tabindex="-1">複習打印、刪除和次行命令 <a class="header-anchor" href="#複習打印、刪除和次行命令" aria-label="Permalink to “複習打印、刪除和次行命令”">​</a></h3><p>現在你已經更熟悉使用保持空間了，我們回到打印、刪除和次行命令。我們已經討論了小寫的 <code>p</code>、<code>d</code> 和 <code>n</code> 命令了。而它們也有大寫的版本。因為每個命令都有大小寫版本，似乎是 Sed 的習慣，這些命令的大寫版本將與多行緩衝區有關：</p><ul><li><code>P</code> 將模式空間中第一個新行之前的內容輸出</li><li><code>D</code> 刪除模式空間中第一個新行之前的內容（包含新行），然後不讀取任何新的輸入而是使用剩餘的文本去重啓一個循環</li><li><code>N</code> 讀取輸入並追加一個新行到模式空間，用一個新行作為新舊數據的分隔符。繼續運行當前的循環。</li></ul><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-delete-upper-command.png?w=702&amp;ssl=1" alt="The Sed uppercase  command"></p><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-next-upper-command.png?w=702&amp;ssl=1" alt="The Sed uppercase  command"></p>`,55)),a("p",null,[s[49]||(s[49]=n("這些命令的使用場景主要用於實現隊列（",-1)),p(e,{href:"https://en.wikipedia.org/wiki/FIFO_(computing_and_electronics)"},{default:i(()=>[...s[48]||(s[48]=[n("FIFO 列表",-1)])]),_:1}),s[50]||(s[50]=n("）。從一個輸入文件中刪除最後 5 行就是一個很權威的例子：",-1))]),s[98]||(s[98]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -En -e &#39;</span></span>
<span class="line"><span>  1 { N;N;N;N } # 確保模式空間中包含 5 行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  N             # 追加第 6 行到隊列中</span></span>
<span class="line"><span>  P             # 輸出隊列的第 1 行</span></span>
<span class="line"><span>  D             # 刪除隊列的第 1 行</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>作為第二個示例，我們可以在兩個列上顯示輸入數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 輸出兩列</span></span>
<span class="line"><span>sed &lt; inputfile -En -e &#39;</span></span>
<span class="line"><span> $!N    # 追加一個新行到模式空間</span></span>
<span class="line"><span>        # 除了輸入文件的最後一行</span></span>
<span class="line"><span>        # 當在輸入文件的最後一行使用 N 命令時</span></span>
<span class="line"><span>        # GNU Sed 和 POSIX Sed 的行為是有差異的</span></span>
<span class="line"><span>        # 需要使用一個技巧去處理這種情況</span></span>
<span class="line"><span>        # https://www.gnu.org/software/sed/manual/sed.html#N_005fcommand_005flast_005fline</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 用空間填充第 1 行的第 1 個字段</span></span>
<span class="line"><span>        # 並丟棄其餘行</span></span>
<span class="line"><span> s/:.*\\n/                    \\n/</span></span>
<span class="line"><span> s/:.*//            # 除了第 2 行上的第 1 個字段外，丟棄其餘的行</span></span>
<span class="line"><span> s/(.{20}).*\\n/\\1/  # 修剪並連接行</span></span>
<span class="line"><span> p                  # 輸出結果</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h3 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to “分支”">​</a></h3>`,4)),a("p",null,[s[52]||(s[52]=n("我們剛才已經看到，Sed 因為有保持空間所以有了緩存的功能。其實它還有測試和分支的指令。因為有這些特性使得 Sed 是一個",-1)),p(e,{href:"https://chortle.ccsu.edu/StructuredC/Chap01/struct01_5.html"},{default:i(()=>[...s[51]||(s[51]=[n("圖靈完備",-1)])]),_:1}),s[53]||(s[53]=n("的語言。雖然它可能看起來很傻，但意味着你可以使用 Sed 寫任何程序。你可以實現任何你的目的，但並不意味着實現起來會很容易，而且結果也不一定會很高效。",-1))]),a("p",null,[s[56]||(s[56]=n("不過不用擔心。在本文中，我們將使用能夠展示測試和分支功能的最簡單的例子。雖然這些功能乍一看似乎很有限，但請記住，有些人用 Sed 寫了 ",-1)),p(e,{href:"http://www.catonmat.net/ftp/sed/dc.sed"},{default:i(()=>[...s[54]||(s[54]=[n("http://www.catonmat.net/ftp/sed/dc.sed",-1)])]),_:1}),s[57]||(s[57]=n(" [計算器]、",-1)),p(e,{href:"http://www.catonmat.net/ftp/sed/sedtris.sed"},{default:i(()=>[...s[55]||(s[55]=[n("http://www.catonmat.net/ftp/sed/sedtris.sed",-1)])]),_:1}),s[58]||(s[58]=n(" [俄羅斯方塊] 或許多其它類型的應用程序！",-1))]),s[99]||(s[99]=l(`<h4 id="標籤和分支" tabindex="-1">標籤和分支 <a class="header-anchor" href="#標籤和分支" aria-label="Permalink to “標籤和分支”">​</a></h4><p>從某些方面，你可以將 Sed 看到是一個功能有限的彙編語言。因此，你不會找到在高級語言中常見的 “for” 或 “while” 循環，或者 “if ... else” 語句，但是你可以使用分支來實現同樣的功能。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-branch-command.png?w=702&amp;ssl=1" alt="The Sed branch command"></p><p>如果你在本文開始部分看到了用流程圖描述的 Sed 運行模型，那麼你應該知道 Sed 會自動增加程序計數器（PC）的值，命令是按程序的指令順序來運行的。但是，使用分支（<code>b</code>）指令，你可以通過選擇執行程序中的任意命令來改變順序運行的程序。跳轉目的地是使用一個標籤（<code>:</code>）來顯式定義的。</p><p><img src="https://i1.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-label-command.png?w=702&amp;ssl=1" alt="The Sed label command"></p><p>這是一個這樣的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo hello | sed -ne &#39;</span></span>
<span class="line"><span>  :start    # 在程序的該行上放置一個 “start” 標籤</span></span>
<span class="line"><span>  p         # 輸出模式空間內容</span></span>
<span class="line"><span>  b start   # 繼續在 :start 標籤上運行</span></span>
<span class="line"><span>&#39; | less</span></span></code></pre></div><p>那個 Sed 程序的行為非常類似於 <code>yes</code> 命令：它獲取一個字符串併產生一個包含那個字符串的無限流。</p><p>切換到一個標籤就像我們繞開了 Sed 的自動化特性一樣：它既不讀取任何輸入，也不輸出任何內容，更不更新任何緩衝區。它只是跳轉到源程序指令順序中下一條的另外一個指令。</p><p>值得一提的是，如果在分支命令（<code>b</code>）上沒有指定一個標籤作為它的參數，那麼分支將直接切換到程序結束的地方。因此，Sed 將啓動一個新的循環。這個特性可以用於去跳過一些指令並且因此可以用於作為“塊”的替代者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -ne &#39;</span></span>
<span class="line"><span>/usb/!b</span></span>
<span class="line"><span>/daemon/!b</span></span>
<span class="line"><span>p</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h4 id="條件分支" tabindex="-1">條件分支 <a class="header-anchor" href="#條件分支" aria-label="Permalink to “條件分支”">​</a></h4><p>到目前為止，我們已經看到了無條件分支，這個術語可能有點誤導嫌疑，因為 Sed 命令總是基於它們的可選地址來作為條件的。</p><p>但是，在傳統意義上，一個無條件分支也是一個分支，當它運行時，將跳轉到特定的目的地，而條件分支既有可能也或許不可能跳轉到特定的指令，這取決於系統的當前狀態。</p><p>Sed 只有一個條件指令，就是測試（<code>t</code>）命令。只有在當前循環的開始或因為前一個條件分支運行了替換，它才跳轉到不同的指令。更多的情況是，只有替換標誌被設置時，測試命令才會切換分支。</p><p><img src="https://i1.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-test-command.png?w=702&amp;ssl=1" alt="The Sed  command"></p><p>使用測試指令，你可以在一個 Sed 程序中很輕鬆地執行一個循環。作為一個特定的示例，你可以用它將一個行填充到某個長度（這是使用正則表達式無法實現的）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 居中文本</span></span>
<span class="line"><span>cut -d: -f1 inputfile | sed -Ee &#39;</span></span>
<span class="line"><span>  :start</span></span>
<span class="line"><span>  s/^(.{,19})$/ \\1 /    # 用一個空格填充少於 20 個字符的行的開始處</span></span>
<span class="line"><span>                        # 並在結束處添加另一個空格</span></span>
<span class="line"><span>  t start               # 如果我們已經添加了一個空格，則返回到 :start 標籤</span></span>
<span class="line"><span>  s/(.{20}).*/| \\1 |/   # 只保留一個行的前 20 個字符</span></span>
<span class="line"><span>                        # 以修復由於奇數行引起的差一錯誤</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>如果你仔細讀前面的示例，你可能注意到，在將要把數據“喂”給 Sed 之前，我通過 <code>cut</code> 命令做了一點小修正去預處理數據。</p><p>不過，我們也可以只使用 Sed 對程序做一些小修改來執行相同的任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat inputfile | sed -Ee &#39;</span></span>
<span class="line"><span>  s/:.*//               # 除第 1 個字段外刪除剩餘字段</span></span>
<span class="line"><span>  t start</span></span>
<span class="line"><span>  :start</span></span>
<span class="line"><span>  s/^(.{,19})$/ \\1 /    # 用一個空格填充少於 20 個字符的行的開始處</span></span>
<span class="line"><span>                        # 並在結束處添加另一個空格</span></span>
<span class="line"><span>  t start               # 如果我們已經添加了一個空格，則返回到 :start 標籤</span></span>
<span class="line"><span>  s/(.{20}).*/| \\1 |/   # 僅保留一個行的前 20 個字符</span></span>
<span class="line"><span>                        # 以修復由於奇數行引起的差一錯誤</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>在上面的示例中，你或許對下列的結構感到驚奇：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>t start</span></span>
<span class="line"><span>:start</span></span></code></pre></div><p>乍一看，在這裏的分支並沒有用，因為它只是跳轉到將要運行的指令處。但是，如果你仔細閲讀了測試命令的定義，你將會看到，如果在當前循環的開始或者前一個測試命令運行後發生了一個替換，分支才會起作用。換句話説就是，測試指令有清除替換標誌的副作用。這也正是上面的代碼片段的真實目的。這是一個在包含條件分支的 Sed 程序中經常看到的技巧，用於在使用多個替換命令時避免出現<ruby>誤報<rt>false positive</rt></ruby>的情況。</p><p>通過它並不能絕對強制地清除替換標誌，我同意這一説法。因為在將字符串填充到正確的長度時我使用的特定的替換命令是<ruby>冪等<rt>idempotent</rt></ruby>的。因此，一個多餘的迭代並不會改變結果。不過，我們可以現在再次看一下第二個示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 基於它們的登錄程序來分類用户帳户</span></span>
<span class="line"><span>cat inputfile | sed -Ene &#39;</span></span>
<span class="line"><span>  s/^/login=/</span></span>
<span class="line"><span>  /nologin/s/^/type=SERV /</span></span>
<span class="line"><span>  /false/s/^/type=SERV /</span></span>
<span class="line"><span>  t print</span></span>
<span class="line"><span>  s/^/type=USER /</span></span>
<span class="line"><span>  :print</span></span>
<span class="line"><span>  s/:.*//p</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>我希望在這裏根據用户默認配置的登錄程序，為用户帳户打上 “SERV” 或 “USER” 的標籤。如果你運行它，預計你將看到 “SERV” 標籤。然而，並沒有在輸出中跟蹤到 “USER” 標籤。為什麼呢？因為 <code>t print</code> 指令不論行的內容是什麼，它總是切換，替換標誌總是由程序的第一個替換命令來設置。一旦替換標誌設置完成後，在下一個行被讀取或直到下一個測試命令之前，這個標誌將保持不變。下面我們給出修復這個程序的解決方案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 基於用户登錄程序來分類用户帳户</span></span>
<span class="line"><span>cat inputfile | sed -Ene &#39;</span></span>
<span class="line"><span>  s/^/login=/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  t classify # clear the &quot;substitution flag&quot;</span></span>
<span class="line"><span>  :classify</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  /nologin/s/^/type=SERV /</span></span>
<span class="line"><span>  /false/s/^/type=SERV /</span></span>
<span class="line"><span>  t print</span></span>
<span class="line"><span>  s/^/type=USER /</span></span>
<span class="line"><span>  :print</span></span>
<span class="line"><span>  s/:.*//p</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h3 id="精確地處理文本" tabindex="-1">精確地處理文本 <a class="header-anchor" href="#精確地處理文本" aria-label="Permalink to “精確地處理文本”">​</a></h3><p>Sed 是一個非交互式文本編輯器。雖然是非交互式的，但仍然是文本編輯器。而如果沒有在輸出中插入一些東西的功能，那它就不算一個完整的文本編輯器。我不是很喜歡它的文本編輯的特性，因為我發現它的語法太難用了（即便是以 Sed 的標準而言），但有時你難免會用到它。</p><p>採用嚴格的 POSIX 語法的只有三個命令：改變（<code>c</code>）、插入（<code>i</code>）或追加（<code>a</code>）一些文字文本到輸出，都遵循相同的特定語法：命令字母后面跟着一個反斜槓，並且文本從腳本的下一行上開始插入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>head -5 inputfile | sed &#39;</span></span>
<span class="line"><span>1i\\</span></span>
<span class="line"><span># List of user accounts</span></span>
<span class="line"><span>$a\\</span></span>
<span class="line"><span># end</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>插入多行文本，你必須每一行結束的位置使用一個反斜槓：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>head -5 inputfile | sed &#39;</span></span>
<span class="line"><span>1i\\</span></span>
<span class="line"><span># List of user accounts\\</span></span>
<span class="line"><span># (users 1 through 5)</span></span>
<span class="line"><span>$a\\</span></span>
<span class="line"><span># end</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>一些 Sed 實現，比如 GNU Sed，在初始的反斜槓後面的換行符是可選的，即便是在 <code>--posix</code> 模式下仍然如此。我在標準中並沒有找到任何關於該替代語法的説明（如果是因為我沒有在標準中找到那個特性，請在評論區留言告訴我！）。因此，如果對可移植性要求很高，請注意使用它的風險：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 非 POSIX 語法：</span></span>
<span class="line"><span>head -5 inputfile | sed -e &#39;</span></span>
<span class="line"><span>1i\\# List of user accounts</span></span>
<span class="line"><span>$a\\# end</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>也有一些 Sed 的實現，讓初始的反斜槓完全是可選的。因此毫無疑問，它是一個廠商對 POSIX 標準進行擴展的特定版本，它是否支持那個語法，你需要去查看那個 Sed 版本的手冊。</p><p>在簡單概述之後，我們現在來回顧一下這些命令的更多細節，從我還沒有介紹的改變命令開始。</p><h4 id="改變命令" tabindex="-1">改變命令 <a class="header-anchor" href="#改變命令" aria-label="Permalink to “改變命令”">​</a></h4><p>改變命令（<code>c\\</code>）就像 <code>d</code> 命令一樣刪除模式空間的內容並開始一個新的循環。唯一的不同在於，當命令運行之後，用户提供的文本是寫往輸出的。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-change-command.png?w=702&amp;ssl=1" alt="The Sed change command"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -e &#39;</span></span>
<span class="line"><span>/systemd/c\\</span></span>
<span class="line"><span># :REMOVED:</span></span>
<span class="line"><span>s/:.*// # This will NOT be applied to the &quot;changed&quot; text</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>如果改變命令與一個地址範圍關聯，當到達範圍的最後一行時，這個文本將僅輸出一次。這在某種程度上成為 Sed 命令將被重複應用在地址範圍內所有行這一慣例的一個例外情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -e &#39;</span></span>
<span class="line"><span>19,22c\\</span></span>
<span class="line"><span># :REMOVED:</span></span>
<span class="line"><span>s/:.*// # This will NOT be applied to the &quot;changed&quot; text</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>因此，如果你希望將改變命令重複應用到地址範圍內的所有行上，除了將它封裝到一個塊中之外，你將沒有其它的選擇：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat -n inputfile | sed -e &#39;</span></span>
<span class="line"><span>19,22{c\\</span></span>
<span class="line"><span># :REMOVED:</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>s/:.*// # This will NOT be applied to the &quot;changed&quot; text</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h4 id="插入命令" tabindex="-1">插入命令 <a class="header-anchor" href="#插入命令" aria-label="Permalink to “插入命令”">​</a></h4><p>插入命令（<code>i\\</code>）將立即在輸出中給出用户提供的文本。它並不以任何方式修改程序流或緩衝區的內容。</p><p><img src="https://i0.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-insert-command.png?w=702&amp;ssl=1" alt="The Sed insert command"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># display the first five user names with a title on the first row</span></span>
<span class="line"><span>sed &lt; inputfile -e &#39;</span></span>
<span class="line"><span>1i\\</span></span>
<span class="line"><span>USER NAME</span></span>
<span class="line"><span>s/:.*//</span></span>
<span class="line"><span>5q</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h4 id="追加命令" tabindex="-1">追加命令 <a class="header-anchor" href="#追加命令" aria-label="Permalink to “追加命令”">​</a></h4><p>當輸入的下一行被讀取時，追加命令（<code>a\\</code>）將一些文本追加到顯示隊列。文本在當前循環的結束部分（包含程序結束的情況）或當使用 <code>n</code> 或 <code>N</code> 命令從輸入中讀取一個新行時被輸出。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-append-command.png?w=702&amp;ssl=1" alt="The Sed append command"></p><p>與上面相同的一個示例，但這次是插入到底部而不是頂部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &lt; inputfile -e &#39;</span></span>
<span class="line"><span>5a\\</span></span>
<span class="line"><span>USER NAME</span></span>
<span class="line"><span>s/:.*//</span></span>
<span class="line"><span>5q</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h4 id="讀取命令" tabindex="-1">讀取命令 <a class="header-anchor" href="#讀取命令" aria-label="Permalink to “讀取命令”">​</a></h4><p>這是插入一些文本內容到輸出流的第四個命令：讀取命令（<code>r</code>）。它的工作方式與追加命令完全一樣，但不同的，它不從 Sed 腳本中取得硬編碼到腳本中的文本，而是把一個文件的內容寫入到一個輸出上。</p><p>讀取命令只調度要讀取的文件。當清理追加隊列時，後者才被高效地讀取，而不是在讀取命令運行時。如果這時候對這個文件有併發的訪問讀取，或那個文件不是一個普通的文件（比如，它是一個字符設備或命名管道），或文件在讀取期間被修改，這時可能會產生嚴重的後果。</p>`,58)),a("p",null,[s[60]||(s[60]=n("作為一個例證，如果你使用我們將在下一節詳細講述的寫入命令，它與讀取命令共同配合從一個臨時文件中寫入並重新讀取，你可能會獲得一些創造性的結果（使用法語版的 ",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Shiritori"},{default:i(()=>[...s[59]||(s[59]=[n("Shiritori",-1)])]),_:1}),s[61]||(s[61]=n(" 遊戲作為一個例證）：",-1))]),s[100]||(s[100]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>printf &quot;%s\\n&quot; &quot;Trois p&#39;tits chats&quot; &quot;Chapeau d&#39; paille&quot; &quot;Paillasson&quot; |</span></span>
<span class="line"><span>sed -ne &#39;</span></span>
<span class="line"><span>  r temp</span></span>
<span class="line"><span>  a\\</span></span>
<span class="line"><span>  ----</span></span>
<span class="line"><span>  w temp</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>現在，在流輸出中專門用於插入一些文本的 Sed 命令清單結束了。我的最後一個示例純屬好玩，但是由於我前面提到過有一個寫入命令，這個示例將我們完美地帶到下一節，在下一節我們將看到在 Sed 中如何將數據寫入到一個外部文件。</p><h3 id="替代的輸出" tabindex="-1">替代的輸出 <a class="header-anchor" href="#替代的輸出" aria-label="Permalink to “替代的輸出”">​</a></h3><p>Sed 的設計思想是，所有的文本轉換都將寫入到進程的標準輸出上。但是，Sed 也有一些特性支持將數據發送到替代的目的地。你有兩種方式去實現上述的輸出目標替換：使用專門的寫入命令（<code>w</code>），或者在一個替換命令（<code>s</code>）上添加一個寫入標誌。</p><h4 id="寫入命令" tabindex="-1">寫入命令 <a class="header-anchor" href="#寫入命令" aria-label="Permalink to “寫入命令”">​</a></h4><p>寫入命令（<code>w</code>）會追加模式空間的內容到給定的目標文件中。POSIX 要求在 Sed 處理任何數據之前，目標文件能夠被 Sed 所創建。如果給定的目標文件已經存在，它將被覆寫。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-write-command.png?w=702&amp;ssl=1" alt="The Sed write command"></p><p>因此，即便是你從未真的寫入到該文件中，但該文件仍然會被創建。例如，下列的 Sed 程序將創建/覆寫這個 <code>output</code> 文件，那怕是這個寫入命令從未被運行過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo | sed -ne &#39;</span></span>
<span class="line"><span>  q # 立刻退出</span></span>
<span class="line"><span>  w output # 這個命令從未被運行</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>你可以將幾個寫入命令指向到同一個目標文件。指向同一個目標文件的所有寫入命令將追加那個文件的內容（工作方式幾乎與 shell 的重定向符 <code>&gt;&gt;</code> 相同）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &lt; inputfile -ne &#39;</span></span>
<span class="line"><span>  /:\\/bin\\/false$/w server</span></span>
<span class="line"><span>  /:\\/usr\\/sbin\\/nologin$/w server</span></span>
<span class="line"><span>  w output</span></span>
<span class="line"><span>&#39;</span></span>
<span class="line"><span>cat server</span></span></code></pre></div><h4 id="替換命令的寫入標誌" tabindex="-1">替換命令的寫入標誌 <a class="header-anchor" href="#替換命令的寫入標誌" aria-label="Permalink to “替換命令的寫入標誌”">​</a></h4><p>在前面，我們已經學習了替換命令（<code>s</code>），它有一個 <code>p</code> 選項用於在替換之後輸出模式空間的內容。同樣它也提供一個類似功能的 <code>w</code> 選項，用於在替換之後將模式空間的內容輸出到一個文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &lt; inputfile -ne &#39;</span></span>
<span class="line"><span>  s/:.*\\/nologin$//w server</span></span>
<span class="line"><span>  s/:.*\\/false$//w server</span></span>
<span class="line"><span>&#39;</span></span>
<span class="line"><span>cat server</span></span></code></pre></div><h3 id="註釋" tabindex="-1">註釋 <a class="header-anchor" href="#註釋" aria-label="Permalink to “註釋”">​</a></h3><p>我無數次使用過它們，但我從未花時間正式介紹過它們，因此，我決定現在來正式地介紹它們：就像大多數編程語言一樣，註釋是添加軟件不去解析的自由格式文本的一種方法。Sed 的語法很晦澀，我不得不強調在腳本中需要的地方添加足夠的註釋。否則，除了作者外其他人將幾乎無法理解它。</p><p><img src="https://i1.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-comment-command.png?w=702&amp;ssl=1" alt="The Sed comment command"></p><p>不過，和 Sed 的其它部分一樣，註釋也有它自己的微妙之處。首先並且是最重要的，註釋並不是語法結構，但它是真正意義的 Sed 命令。註釋雖然是一個“什麼也不做”的命令，但它仍然是一個命令。至少，它是在 POSIX 中定義了的。因此，嚴格地説，它們只允許使用在其它命令允許使用的地方。</p><p>大多數 Sed 實現都通過允許行內命令來放鬆了那種要求，就像在那個文章中我到處都使用的那樣。</p><p>結束那個主題之前，需要説一下 <code>#n</code> 註釋（<code>#</code> 後面緊跟一個字母 <code>n</code>，中間沒有空格）的特殊情況。如果在腳本的第一行找到這個精確註釋，Sed 將切換到靜默模式（即：清除自動輸出標誌），就像在命令列上指定了 <code>-n</code> 選項一樣。</p><h3 id="很少用得到的命令" tabindex="-1">很少用得到的命令 <a class="header-anchor" href="#很少用得到的命令" aria-label="Permalink to “很少用得到的命令”">​</a></h3><p>現在，我們已經學習的命令能讓你寫出你所用到的 99.99% 的腳本。但是，如果我沒有提到剩餘的 Sed 命令，那麼本教程就不能稱為完全指南。我把它們留到最後是因為我們很少用到它。但或許你有實際使用案例，那麼你就會發現它們很有用。如果是那樣，請不要猶豫，在下面的評論區中把它分享給我們吧。</p><h4 id="行數命令" tabindex="-1">行數命令 <a class="header-anchor" href="#行數命令" aria-label="Permalink to “行數命令”">​</a></h4><p>這個 <code>=</code> 命令將向標準輸出上顯示當前 Sed 正在讀取的行數，這個行數就是行計數器（<code>LC</code>）的內容。沒有任何方式從任何一個 Sed 緩衝區中捕獲那個數字，也不能對它進行輸出格式化。由於這兩個限制使得這個命令的可用性大大降低。</p><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-current-line-command.png?w=702&amp;ssl=1" alt="The Sed line number command"></p><p>請記住，在嚴格的 POSIX 兼容模式中，當在命令列上給定幾個輸入文件時，Sed 並不重置那個計數器，而是連續地增長它，就像所有的輸入文件是連接在一起的一樣。一些 Sed 實現，像 GNU Sed，它就有一個選項可以在每個輸入文件讀取結束後去重置計數器。</p><h4 id="明確打印命令" tabindex="-1">明確打印命令 <a class="header-anchor" href="#明確打印命令" aria-label="Permalink to “明確打印命令”">​</a></h4>`,27)),a("p",null,[s[63]||(s[63]=n("這個 ",-1)),s[64]||(s[64]=a("code",null,"l",-1)),s[65]||(s[65]=n("（小寫的字母 ",-1)),s[66]||(s[66]=a("code",null,"l",-1)),s[67]||(s[67]=n("）作用類似於打印命令（",-1)),s[68]||(s[68]=a("code",null,"p",-1)),s[69]||(s[69]=n("），但它是以精確的格式去輸出模式空間的內容。以下引用自 ",-1)),p(e,{href:"http://pubs.opengroup.org/onlinepubs/9699919799/utilities/sed.html"},{default:i(()=>[...s[62]||(s[62]=[n("POSIX 標準",-1)])]),_:1}),s[70]||(s[70]=n("：",-1))]),s[101]||(s[101]=l('<blockquote><p>在 XBD 轉義序列中列出的字符和相關的動作（<code>\\\\</code>、<code>\\a</code>、<code>\\b</code>、<code>\\f</code>、<code>\\r</code>、<code>\\t</code>、<code>\\v</code>）將被寫為相應的轉義序列；在那個表中的 <code>\\n</code> 是不適用的。不在那個表中的不可打印字符將被寫為一個三位八進制數字（在前面使用一個反斜槓 <code>\\</code>），表示字符中的每個字節（最重要的字節在前面）。長行應該被換行，通過寫一個反斜槓後跟一個換行符來表示換行位置；發生換行時的長度是不確定的，但應該適合輸出設備的具體情況。每個行應該以一個 <code>$</code> 標記結束。</p></blockquote><p><img src="https://i2.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-unambiguous-print-command.png?w=702&amp;ssl=1" alt="The Sed unambiguous print command"></p>',2)),a("p",null,[s[72]||(s[72]=n("我懷疑這個命令是在非 ",-1)),p(e,{href:"https://en.wikipedia.org/wiki/8-bit_clean"},{default:i(()=>[...s[71]||(s[71]=[n("8 位規則化信道",-1)])]),_:1}),s[73]||(s[73]=n(" 上交換數據的。就我本人而言，除了調試用途以外，也從未使用過它。",-1))]),s[102]||(s[102]=l(`<h4 id="移譯命令" tabindex="-1">移譯命令 <a class="header-anchor" href="#移譯命令" aria-label="Permalink to “移譯命令”">​</a></h4><p><ruby>移譯<rt>transliterate</rt></ruby>（<code>y</code>）命令允許從一個源集到一個目標集映射模式空間的字符。它非常類似於 <code>tr</code> 命令，但是限制更多。</p><p><img src="https://i1.wp.com/linuxhandbook.com/wp-content/uploads/2018/05//sed-transliterate-command.png?w=702&amp;ssl=1" alt="The Sed transliterate command"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># The \`y\` c0mm4nd 1s for h4x0rz only</span></span>
<span class="line"><span>sed &lt; inputfile -e &#39;</span></span>
<span class="line"><span> s/:.*//</span></span>
<span class="line"><span> y/abcegio/48&lt;3610/</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><p>雖然移譯命令語法與替換命令的語法有一些相似之處，但它在替換字符串之後不接受任何選項。這個移譯總是全局的。</p><p>請注意，移譯命令要求源集和目標集之間要一一對應地轉換。這意味着下面的 Sed 程序可能所做的事情並不是你乍一看所想的那樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 注意：這可能並不如你想的那樣工作！</span></span>
<span class="line"><span>sed &lt; inputfile -e &#39;</span></span>
<span class="line"><span>  s/:.*//</span></span>
<span class="line"><span>  y/[a-z]/[A-Z]/</span></span>
<span class="line"><span>&#39;</span></span></code></pre></div><h3 id="寫在最後的話" tabindex="-1">寫在最後的話 <a class="header-anchor" href="#寫在最後的話" aria-label="Permalink to “寫在最後的話”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 它要做什麼？</span></span>
<span class="line"><span># 提示：答案就在不遠處...</span></span>
<span class="line"><span>sed -E &#39;</span></span>
<span class="line"><span>  s/.*\\W(.*)/\\1/</span></span>
<span class="line"><span>  h</span></span>
<span class="line"><span>  \${ x; p; }</span></span>
<span class="line"><span>  d&#39; &lt; inputfile</span></span></code></pre></div><p>我們已經學習了所有的 Sed 命令，真不敢相信我們已經做到了！如果你也讀到這裏了，應該恭喜你，尤其是如果你花費了一些時間，在你的系統上嘗試了所有的不同示例！</p><p>正如你所見，Sed 是非常複雜的，不僅因為它的語法比較零亂，也因為許多極端案例或命令列為之間的細微差別。毫無疑問，我們可以將這些歸結於歷史的原因。儘管它有這麼多缺點，但是 Sed 仍然是一個非常強大的工具，甚至到現在，它仍然是 Unix 工具箱中為數不多的大量使用的命令之一。是時候總結一下這篇文章了，沒有你們的支持我將無法做到：請節選你對喜歡的或最具創意的 Sed 腳本，並共享給我們。如果我收集到的你們共享出的腳本足夠多了，我將會把這些 Sed 腳本結集發佈！</p><hr>`,12)),a("p",null,[s[75]||(s[75]=n("via: ",-1)),p(e,{href:"https://linuxhandbook.com/sed-reference-guide/"},{default:i(()=>[...s[74]||(s[74]=[n("https://linuxhandbook.com/sed-reference-guide/",-1)])]),_:1})]),a("p",null,[s[80]||(s[80]=n("作者：",-1)),p(e,{href:"https://linuxhandbook.com/author/sylvain/"},{default:i(()=>[...s[76]||(s[76]=[n("Sylvain Leroux",-1)])]),_:1}),s[81]||(s[81]=n(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[77]||(s[77]=[n("lujun9972",-1)])]),_:1}),s[82]||(s[82]=n(" 譯者：",-1)),p(e,{href:"https://github.com/qhwdw"},{default:i(()=>[...s[78]||(s[78]=[n("qhwdw",-1)])]),_:1}),s[83]||(s[83]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[79]||(s[79]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[86]||(s[86]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[84]||(s[84]=[n("LCTT",-1)])]),_:1}),s[87]||(s[87]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[85]||(s[85]=[n("Linux中國",-1)])]),_:1}),s[88]||(s[88]=n(" 榮譽推出",-1))])])}const C=t(r,[["render",h]]);export{y as __pageData,C as default};
